#!/data/data/com.termux/files/usr/bin/bash
# apply_all36.sh - العلوم الفيزيائية للأولى ثانوي (جذع مشترك علوم وتكنولوجيا): الجزء 1 = 35 بطاقة + الخرائط الذهنية (زر 🗺️)
# لا يمسّ مفتاح الترخيص: يضيف ملفات جديدة ووسوم script فقط في index.html بعد نسخة احتياطية.
cd ~/zad-1am/www 2>/dev/null || cd "$(dirname "$0")/www" || { echo "لم أجد مجلد www"; exit 1; }
[ -f index.html.bak_p1 ] || cp index.html index.html.bak_p1

# --- اكتشاف مفتاح مادة العلوم الفيزيائية في الأولى ثانوي (شعبة جذع مشترك علوم وتكنولوجيا) من db.js ---
CH=$(tr -d '\n' < db.js | sed 's/"AS1": *{"name"/\n&/' | tail -1 | sed 's/"AS2": *{"name".*//')
KEY=$(printf '%s' "$CH" | grep -o '"key": *"[^"]*", *"name": *"العلوم الفيزيائية"' | head -1 | sed 's/"key": *"\([^"]*\)".*/\1/')
NK=$(printf '%s' "$CH" | grep -o '"key": *"[^"]*", *"name": *"العلوم الفيزيائية"' | wc -l)
if [ -z "$KEY" ]; then
  KEY=$(printf '%s' "$CH" | grep -o '"key": *"physics"' | head -1 | sed 's/"key": *"\([^"]*\)".*/\1/')
  NK=$(printf '%s' "$CH" | grep -o '"key": *"physics"' | wc -l)
fi
if [ -z "$KEY" ]; then
  printf '%s' "$CH" | head -c 3000 > ~/storage/downloads/p1_diag.txt
  echo "لم أجد مادة العلوم الفيزيائية للأولى ثانوي في db.js. كتبتُ تشخيصا في التنزيلات: p1_diag.txt - أرسله لي."
  echo "لم يُغيَّر شيء."
  exit 1
fi
echo "مفتاح المادة: $KEY (عدد الشعب التي فيها هذه المادة: $NK)"
[ "$NK" -gt 1 ] && echo "تنبيه: المادة موجودة في أكثر من شعبة؛ إن كان لها المفتاح نفسه فستظهر الدروس فيها كلها."

cat > p1_data.js <<'ZAD_EOF'
