var P1_DATA=
[{"n": 1, "m": 1, "i": "🔦", "t": "الانعكاس والانكسار: تذكير وتعريف", "B": [["الانعكاس", ["يرتد الشعاع الضوئي عند سطح فاصل ويبقى في الوسط نفسه", "زاوية السقوط تساوي زاوية الانعكاس", "الشعاع الساقط والمنعكس والناظم في مستوى واحد"]], ["الانكسار", ["ينفذ الشعاع إلى الوسط الشفاف الثاني ويغيّر اتجاهه", "يحدث عند السطح الفاصل بين وسطين شفافين مختلفين", "إذا سقط الشعاع عموديا (على الناظم) لا ينحرف"]], ["العناصر الهندسية", ["الناظم: عمود على السطح الفاصل عند نقطة السقوط", "زاوية السقوط `i` بين الشعاع الساقط والناظم", "زاوية الانكسار `r` بين الشعاع المنكسر والناظم"]]], "K": "الانكسار تغيّر اتجاه الشعاع الضوئي عند عبوره سطحا فاصلا بين وسطين شفافين مختلفين، والزوايا تقاس دائما من الناظم.", "M": ["ارسم الناظم أولا ثم قس الزوايا منه لا من السطح", "الانعكاس: `i = r'` ، الانكسار: `i ≠ r` عموما", "السقوط عموديا = لا انحراف"], "X": "كرة تتدحرج من أرض صلبة إلى رمل: عندما تدخل الرمل بميل تتباطأ فيتغيّر اتجاهها. الضوء يفعل ذلك عند دخوله وسطا آخر.", "EX": [["شعاع ساقط على سطح الماء بزاوية سقوط `0°`. ما اتجاهه بعد العبور؟", "الشعاع ساقط على الناظم، فلا ينحرف ويواصل مساره نفسه."], ["ما الفرق بين الانعكاس والانكسار؟", "في الانعكاس يرتد الشعاع إلى الوسط نفسه، وفي الانكسار ينفذ إلى الوسط الثاني ويغيّر اتجاهه."]]}, {"n": 2, "m": 1, "i": "📐", "t": "قانونا الانكسار (سنيل-ديكارت)", "B": [["القانون الأول", ["الشعاع الساقط والمنكسر والناظم في مستوى السقوط نفسه"]], ["القانون الثاني", ["`n_{1} sin i = n_{2} sin r`", "`n_{1}` قرينة الوسط الأول و `n_{2}` قرينة الوسط الثاني", "يكتب أيضا: `sin i / sin r = n_{2} / n_{1}`"]], ["الاتجاه", ["`n_{2} > n_{1}`: يقترب الشعاع من الناظم `(r < i)`", "`n_{2} < n_{1}`: يبتعد عن الناظم `(r > i)`"]]], "K": "قانون الانكسار: `n_{1} sin i = n_{2} sin r` ، فالشعاع يقترب من الناظم عند دخوله وسطا أكثر انكسارا.", "M": ["حدّد الوسط الأول والثاني ثم عوّض في `n_{1} sin i = n_{2} sin r`", "احسب `sin r` ثم استعمل `sin⁻¹` في الآلة (وضع الدرجات)", "قارن القرينتين لتتحقق من اتجاه الانحراف"], "X": "الوسط ذو القرينة الكبيرة «ثقيل» على الضوء: يدخله فيميل نحو العمود (الناظم) كمن يسير بحذ